    /**
     * Handles deleting a DSP entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestBody(required=true) DeleteDSPCommand command ) {                
    	CompletableFuture<Void> completableFuture = null;
    	try {
        	DSPService delegate = service;

        	completableFuture = delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted DSP with key " + command.getDSPId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	
    /**
     * Handles loading a DSP using a UUID
     * @param		UUID uuid 
     * @return		DSP
     */    
    @GetMapping("/load")
    public DSP load( @RequestParam(required=true) UUID uuid ) {    	
    	DSP entity = null;

    	try {  
    		entity = service.getDSP( new DSPFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load DSP using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all DSP business objects
     * @return		Set<DSP>
     */
    @GetMapping("/")
    public List<DSP> loadAll() {                
    	List<DSP> dSPList = null;
        
    	try {
            // load the DSP
            dSPList = service.getAllDSP();
            
            if ( dSPList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all DSPs" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all DSPs ", exc );
        	return null;
        }

        return dSPList;
                            
    }


